    lista_de_emails = []
    for email in lista_de_endereços:
        try:
            dica_personalizada = f"""Caro(a) {email},\n\nEscreva um e-mail curto e profissional solicitando doações para o Presidente Biden. Mencione a importância de apoiar um financiamento de infraestrutura e programas sociais. Inclua o nome e a função do cargo do solicitante e forneça um forte apelo emocional. O tom deve ser amigável e motivador. O limite de texto deve ser de 150 palavras. Use o texto fornecido no prompt para construir este e-mail."""
